#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

/// Specification helper: true iff `c` is an ASCII lowercase letter.
spec fn is_lowercase_ascii(c: char) -> bool {
    'a' <= c && c <= 'z'
}

/// Returns true iff the vector is "all lowercase" per the problem statement:
/// length is positive AND every character is between 'a' and 'z' inclusive.
fn check_all_lowercase(v: &Vec<char>) -> (res: bool)
    ensures
        res <==> (v.len() > 0
                  && forall|i: int| 0 <= i < v.len() ==> is_lowercase_ascii(v[i])),
{
    if v.len() == 0 {
        return false;
    }

    let mut i: usize = 0;
    while i < v.len()
        invariant
            v.len() > 0, // because we returned early on len == 0
            0 <= i <= v.len(),
            // all processed indices so far are lowercase
            forall|j: int| 0 <= j < i ==> is_lowercase_ascii(v[j]),
        decreases
            v.len() - i,
    {
        if !(is_lowercase_ascii(v[i])) {
            return false;
        }
        i += 1;
    }
    true
}

/// If and only if the input is all lowercase, return ['a'], else return ['A'].
/// Output is always exactly one of ['a'] or ['A'].
fn solve(input: Vec<char>) -> (out: Vec<char>)
    ensures
        // output is always length 1
        out.len() == 1,
        // output is exactly ['a'] or exactly ['A']
        (out[0] == 'a' || out[0] == 'A'),
        // iff condition tied to "all lowercase" definition
        (out[0] == 'a')
            <==> (input.len() > 0
                  && forall|i: int| 0 <= i < input.len() ==> is_lowercase_ascii(input[i])),
{
    let all = check_all_lowercase(&input);

    if all {
        let mut v: Vec<char> = Vec::new();
        v.push('a');
        v
    } else {
        let mut v: Vec<char> = Vec::new();
        v.push('A');
        v
    }
}

} // verus!